document.addEventListener("DOMContentLoaded", function () { function initMeetingPricingCalculator() { const meetingTypeCards = document.querySelectorAll('.meeting-type-card'); const hoursInput = document.getElementById('hoursInput'); const decreaseHoursBtn = document.getElementById('decreaseHours'); const increaseHoursBtn = document.getElementById('increaseHours'); const selectedSessionTypeEl = document.getElementById('selectedSessionType'); const pricePerSessionEl = document.getElementById('pricePerSession'); const numberOfHoursEl = document.getElementById('numberOfHours'); const totalAmountEl = document.getElementById('totalAmount'); const proceedToPaymentBtn = document.getElementById('proceedToPaymentButton'); const paymentSection = document.getElementById('paymentSection'); const backToSelectionBtn = document.getElementById('backToSelectionButton'); const submitPaymentBtn = document.getElementById('submitPaymentButton'); const summarySessionTypeEl = document.getElementById('summarySessionType'); const summaryDurationEl = document.getElementById('summaryDuration'); const summaryHoursEl = document.getElementById('summaryHours'); const summaryTotalEl = document.getElementById('summaryTotal'); const paymentAmountEl = document.getElementById('paymentAmount'); let selectedPrice = 15; let selectedType = 'Quick Chat'; let selectedDuration = '30 minutes'; let hours = 1; function updateCalculation() { selectedSessionTypeEl.textContent = selectedType; pricePerSessionEl.textContent = `${selectedPrice}`; numberOfHoursEl.textContent = hours; totalAmountEl.textContent = `$${selectedPrice * hours}`; if (summarySessionTypeEl) summarySessionTypeEl.textContent = selectedType; if (summaryDurationEl) summaryDurationEl.textContent = selectedDuration; if (summaryHoursEl) summaryHoursEl.textContent = hours; if (summaryTotalEl) summaryTotalEl.textContent = `$${selectedPrice * hours}`; if (paymentAmountEl) paymentAmountEl.textContent = `$${selectedPrice * hours}` } meetingTypeCards.forEach(card => { card.addEventListener('click', function () { meetingTypeCards.forEach(c => c.classList.remove('active')); this.classList.add('active'); selectedPrice = parseInt(this.dataset.price); selectedType = this.querySelector('h3').textContent; selectedDuration = this.querySelector('.duration').textContent; updateCalculation() }) }); hoursInput.addEventListener('change', function () { hours = parseInt(this.value); if (hours < 1) { hours = 1; this.value = 1 } else if (hours > 10) { hours = 10; this.value = 10 } updateCalculation() }); decreaseHoursBtn.addEventListener('click', function () { if (hours > 1) { hours--; hoursInput.value = hours; updateCalculation() } }); increaseHoursBtn.addEventListener('click', function () { if (hours < 10) { hours++; hoursInput.value = hours; updateCalculation() } }); updateCalculation(); window.getBookingSessionData = function () { return { sessionType: selectedType, duration: selectedDuration, hours: hours, price: selectedPrice, amount: selectedPrice * hours } }; if (proceedToPaymentBtn) { proceedToPaymentBtn.addEventListener('click', function () { const scheduleContent = document.getElementById('scheduleSelectionContent'); const inlineBookingForm = document.getElementById('inlineBookingForm'); if (scheduleContent && inlineBookingForm) { scheduleContent.style.display = 'none'; inlineBookingForm.style.display = 'block'; var sectionHeader = document.querySelector('.schedule-card .section-header'); if (sectionHeader) sectionHeader.style.display = 'none'; const scheduleCard = document.querySelector('.schedule-card'); if (scheduleCard) { scheduleCard.scrollIntoView({ behavior: 'smooth', block: 'start' }) } if (typeof window.initInlineBookingForm === 'function') { window.initInlineBookingForm() } } }) } const closePaymentBtn = document.getElementById('closePaymentBtn'); if (closePaymentBtn) { closePaymentBtn.addEventListener('click', function () { if (paymentSection) { paymentSection.classList.remove('active'); document.body.style.overflow = '' } }) } if (backToSelectionBtn) { backToSelectionBtn.addEventListener('click', function () { if (paymentSection) { paymentSection.classList.remove('active'); document.body.style.overflow = '' } }) } if (submitPaymentBtn) { submitPaymentBtn.addEventListener('click', function (e) { e.preventDefault(); const cardNumber = document.getElementById('cardNumber').value; const expiryDate = document.getElementById('expiryDate').value; const cvv = document.getElementById('cvv').value; const cardName = document.getElementById('cardName').value; const email = document.getElementById('email').value; const streetAddress = document.getElementById('streetAddress').value; const city = document.getElementById('city').value; const state = document.getElementById('state').value; const zipCode = document.getElementById('zipCode').value; if (!cardNumber || !expiryDate || !cvv || !cardName || !email || !streetAddress || !city || !state || !zipCode) { alert('Please fill in all required fields'); return } if (!/^\d{16}$/.test(cardNumber.replace(/\s/g, ''))) { alert('Please enter a valid 16-digit card number'); return } if (!/^\d{2}\/\d{2}$/.test(expiryDate)) { alert('Please enter a valid expiry date (MM/YY)'); return } if (!/^\d{3,4}$/.test(cvv)) { alert('Please enter a valid CVV code'); return } if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { alert('Please enter a valid email address'); return } alert('Payment successful! Your session has been booked.'); const paymentContainer = paymentSection.querySelector('.payment-container'); if (paymentContainer) { paymentContainer.innerHTML = `<div class="payment-success"><button id="closeSuccessBtn" class="close-payment-btn"><i class="fa fa-times"></i></button><div class="success-icon"><i class="fa fa-check-circle"></i></div><h3>Payment Successful!</h3><p>Your session has been booked. You will receive a confirmation email shortly.</p><div class="booking-details"><div class="detail-item"><span class="detail-label">Session:</span><span class="detail-value">${selectedType}</span></div><div class="detail-item"><span class="detail-label">Duration:</span><span class="detail-value">${selectedDuration}</span></div><div class="detail-item"><span class="detail-label">Hours:</span><span class="detail-value">${hours}</span></div><div class="detail-item"><span class="detail-label">Total Paid:</span><span class="detail-value">$${selectedPrice * hours}</span></div></div></div>`; setTimeout(() => { const closeSuccessBtn = document.getElementById('closeSuccessBtn'); if (closeSuccessBtn) { closeSuccessBtn.addEventListener('click', function () { if (paymentSection) { paymentSection.classList.remove('active'); document.body.style.overflow = '' } }) } }, 100) } }) } } if (document.querySelector('.meeting-types') && document.getElementById('hoursInput') && document.getElementById('selectedSessionType')) { initMeetingPricingCalculator() } window.addEventListener("load", () => { const preloader = document.querySelector(".preloader"); if (preloader) { preloader.style.display = "none" } }); const menuInputs = document.querySelectorAll("input[name='menu']"); const rightCards = document.querySelectorAll('.right-cards'); menuInputs.forEach(input => { input.addEventListener("change", event => { const targetId = event.target.id; const targetCard = document.querySelector(`.${targetId}`); if (targetCard) { rightCards.forEach(card => card.style.display = 'none'); targetCard.style.display = 'block'; targetCard.scrollIntoView({ behavior: "smooth" }) } }) }); function initMobileFilterDropdowns() { const dropdowns = document.querySelectorAll('.mobile-filter-dropdown'); dropdowns.forEach(dropdown => { const trigger = dropdown.querySelector('.mobile-filter-trigger'); const menu = dropdown.querySelector('.mobile-filter-dropdown-menu'); const options = dropdown.querySelectorAll('.mobile-filter-option'); const currentFilterSpan = trigger.querySelector('.current-filter span'); const currentFilterIcon = trigger.querySelector('.current-filter i'); trigger.addEventListener('click', (e) => { e.preventDefault(); e.stopPropagation(); dropdowns.forEach(otherDropdown => { if (otherDropdown !== dropdown) { otherDropdown.classList.remove('active') } }); dropdown.classList.toggle('active') }); options.forEach(option => { option.addEventListener('click', (e) => { e.preventDefault(); e.stopPropagation(); const category = option.dataset.category; const optionText = option.querySelector('.option-content span').textContent; const optionIcon = option.querySelector('.option-content i').className; options.forEach(opt => opt.classList.remove('active')); option.classList.add('active'); currentFilterSpan.textContent = optionText; currentFilterIcon.className = optionIcon; trigger.dataset.current = category; dropdown.classList.remove('active'); if (dropdown.closest('.works-filter-section')) { filterProjects(category) } else if (dropdown.closest('.certification-filter-section')) { filterCertifications(category) } }) }) }); document.addEventListener('click', (e) => { if (!e.target.closest('.mobile-filter-dropdown')) { dropdowns.forEach(dropdown => { dropdown.classList.remove('active') }) } }) } function filterProjects(category) { const projects = document.querySelectorAll('.works-item'); projects.forEach(project => { if (category === 'All' || project.dataset.category === category) { project.style.display = 'block'; project.classList.remove('fade-out'); project.classList.add('fade-in') } else { project.classList.add('fade-out'); setTimeout(() => { project.style.display = 'none' }, 300) } }); const desktopButtons = document.querySelectorAll('.works-filter-section .filter-btn'); desktopButtons.forEach(btn => { btn.classList.remove('active'); if (btn.dataset.category === category) { btn.classList.add('active') } }) } function filterCertifications(category) { const certifications = document.querySelectorAll('.certification-card'); certifications.forEach(cert => { if (category === 'all' || cert.dataset.category === category) { cert.style.display = 'block'; cert.classList.remove('fade-out'); cert.classList.add('fade-in') } else { cert.classList.add('fade-out'); setTimeout(() => { cert.style.display = 'none' }, 300) } }); const desktopButtons = document.querySelectorAll('.certification-filter-section .filter-btn'); desktopButtons.forEach(btn => { btn.classList.remove('active'); if (btn.dataset.category === category) { btn.classList.add('active') } }) } initMobileFilterDropdowns(); const desktopFilterButtons = document.querySelectorAll('.filter-btn'); desktopFilterButtons.forEach(button => { button.addEventListener('click', (e) => { e.preventDefault(); const category = button.dataset.category; const filterSection = button.closest('.works-filter-section, .certification-filter-section'); const buttons = filterSection.querySelectorAll('.filter-btn'); buttons.forEach(btn => btn.classList.remove('active')); button.classList.add('active'); if (filterSection.classList.contains('works-filter-section')) { filterProjects(category); const mobileDropdown = filterSection.querySelector('.mobile-filter-dropdown'); if (mobileDropdown) { const trigger = mobileDropdown.querySelector('.mobile-filter-trigger'); const currentFilterSpan = trigger.querySelector('.current-filter span'); const currentFilterIcon = trigger.querySelector('.current-filter i'); const targetOption = mobileDropdown.querySelector(`[data-category="${category}"]`); if (targetOption) { currentFilterSpan.textContent = targetOption.querySelector('.option-content span').textContent; currentFilterIcon.className = targetOption.querySelector('.option-content i').className; trigger.dataset.current = category; const mobileOptions = mobileDropdown.querySelectorAll('.mobile-filter-option'); mobileOptions.forEach(opt => opt.classList.remove('active')); targetOption.classList.add('active') } } } else if (filterSection.classList.contains('certification-filter-section')) { filterCertifications(category); const mobileDropdown = filterSection.querySelector('.mobile-filter-dropdown'); if (mobileDropdown) { const trigger = mobileDropdown.querySelector('.mobile-filter-trigger'); const currentFilterSpan = trigger.querySelector('.current-filter span'); const currentFilterIcon = trigger.querySelector('.current-filter i'); const targetOption = mobileDropdown.querySelector(`[data-category="${category}"]`); if (targetOption) { currentFilterSpan.textContent = targetOption.querySelector('.option-content span').textContent; currentFilterIcon.className = targetOption.querySelector('.option-content i').className; trigger.dataset.current = category; const mobileOptions = mobileDropdown.querySelectorAll('.mobile-filter-option'); mobileOptions.forEach(opt => opt.classList.remove('active')); targetOption.classList.add('active') } } } }) }) });